    mr,mc=next((r,c) for r in range(h) for c in range(w) if grid[r][c]==2)
    # Main ray points down from marker. At each row with horizontal barriers,
    # a gap lights its own column vertically toward the nearest barrier.
    for r in range(mr+1,h):
        if grid[r][mc]==8: break
        out[r][mc]=2
    for r in range(h):
        if 8 not in grid[r]: continue
        for c,v in enumerate(grid[r]):
            if v==0:
                for d in (-1,1):
                    rr=r+d
                    while 0<=rr<h and grid[rr][c]!=8:
                        out[rr][c]=2; rr+=d
    # Each lit vertical gap column reflects horizontally from its crossings,
    # but only along the row of the marker ray's horizontal traversal.
    for r in range(h):
        if r==mr: continue
        for c in range(w):
            if out[r][c]==2 and grid[r][c]==0 and any(grid[x][c]==8 for x in range(h)):
                for d in (-1,1):
                    cc=c+d
                    while 0<=cc<w and grid[r][cc]!=8:
                        out[r][cc]=2; cc+=d
    return out

