    # Rays pass between parallel obstacle rows through their holes. Mark
    # vertical columns of holes, then connect adjacent portals in each open band.
    walls=[r for r in range(h) if 8 in grid[r]]
    gaps={r:[c for c,v in enumerate(grid[r]) if v==0] for r in walls}
    for r in range(mr):
        if grid[r][mc]==0: out[r][mc]=2
    # marker ray extends down to first horizontal wall; if the wall has gap
    # points, spread across the band between this wall and the next wall.
    for r in range(mr+1,h):
        if 8 in grid[r]: break
        out[r][mc]=2
    for i,r in enumerate(walls):
        gs=gaps[r]
        if not gs: continue
        prev=walls[i-1] if i else -1
        nxt=walls[i+1] if i+1<len(walls) else h
        # propagate each gap vertically through the adjoining empty bands
        for c in gs:
            for rr in range(prev+1,nxt):
                if grid[rr][c]==0: out[rr][c]=2
        # between neighboring barrier rows, connect the range of their holes
        if i+1<len(walls):
            cs=gs+gaps[walls[i+1]]
            lo,hi=min(cs),max(cs)
            for rr in range(r+1,walls[i+1]):
                for c in range(lo,hi+1):
                    if grid[rr][c]==0: out[rr][c]=2
    return out
